let filter='all';const grid=document.querySelector('#grid'),toast=document.querySelector('#toast');function show(m){toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3000)}function render(){let q=document.querySelector('#search').value.toLowerCase();let a=data.filter(x=>(filter==='all'||x.k===filter)&&(`${x.t} ${x.p}`).toLowerCase().includes(q));document.querySelector('#empty').hidden=!!a.length;grid.innerHTML=a.map(x=>`<article class="card ${x.o?'':'locked'}"><div><div class="cover"></div><div class="meta"><span>${x.l}</span><span>${x.d}</span></div><h3>${x.t}</h3><p>${x.p}</p></div><div class="link" data-open="${!!x.o}">${x.o?'Читать статью →':'Открыть по подписке →'}</div></article>`).join('');document.querySelectorAll('.link').forEach(b=>b.onclick=()=>show(b.dataset.open==='true'?'Статья открыта — здесь появится полный текст.':'Эта статья доступна участникам журнала. Нажмите «Получить доступ».'))}document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;render()});document.querySelector('#search').oninput=render;document.querySelector('#subscribe').onclick=()=>show('Демо: окно оплаты подключим на следующем этапе.');document.querySelector('#login').onclick=()=>show('Демо: здесь будет вход для читателей.');render();
